import unittest

from app.streaks import streak


class StreakTest(unittest.TestCase):
    def test_days_in_a_row(self):
        self.assertEqual(streak(["2026-10-01", "2026-10-02", "2026-10-03"]), 3)

    def test_a_gap_starts_again(self):
        self.assertEqual(streak(["2026-10-01", "2026-10-03", "2026-10-04"]), 2)

import calendar


def days_in(year, month):
    return calendar.monthrange(year, month)[1]
